int cavalry_recording_close(cavalry_recording_t *recording);

/*
 Fills `constants` from the handle.

 # Safety

 `replay` is null or a live replay handle; `constants` is null or writable.
 */
int cavalry_replay_constants(const cavalry_replay_t *replay,
                             cavalry_replay_constants_t *constants);

/*
 How far the replayer has written the replay.

 # Safety

 `replay` is null or a live replay handle.
 */
int64_t cavalry_replay_position(const cavalry_replay_t *replay);

/*
 Whether the replay has ended; when it has, the end position and the reason,
 `CAVALRY_REPLAY_STOP_*` or −1 for none, are written through the non-null pointers.

 # Safety

 `replay` is null or a live replay handle; `position` and `reason` are null or
 writable.
 */
bool cavalry_replay_ended(const cavalry_replay_t *replay,
                          int64_t *position,
                          int32_t *reason);

/*
 Frees the handle; the replay itself is stopped by `cavalry_stop_replay`.

 # Safety

 `replay` is null or a live replay handle, closed once.
 */
int cavalry_replay_close(cavalry_replay_t *replay);

/*
 Polls the subscription's images in turn, handing each fragment to `handler` with
 `clientd`, up to `fragment_limit` fragments; returns the fragments delivered, or
 −1 with the fault as the error and in `cavalry_subscription_fault`.

 # Safety

 `subscription` is null or a live handle not in use by another call; `handler` is
 null or a function that returns, without unwinding or a `longjmp`, and holds the
 rules of "Calls during a claim or a poll".
 */
int cavalry_subscription_poll(cavalry_subscription_t *subscription,
                              cavalry_fragment_handler_t handler,
                              void *clientd,
                              size_t fragment_limit);

/*
 Fills `fault` with what the last poll stopped on.

 # Safety

 `subscription` is null or a live handle; `fault` is null or writable.
 */
int cavalry_subscription_fault(const cavalry_subscription_t *subscription,
                               cavalry_fault_t *fault);

/*
 How many images the subscription holds.

 # Safety

 `subscription` is null or a live handle not in use by another call.
 */
int cavalry_subscription_image_count(const cavalry_subscription_t *subscription);

/*
 The image at `index`, valid until the subscription's next poll or close; null past
 the count, with no error set.

 # Safety

 `subscription` is null or a live handle not in use by another call.
 */
cavalry_image_t *cavalry_subscription_image_at_index(cavalry_subscription_t *subscription,
                                                     size_t index);

/*
 Fills `constants` from the image.

 # Safety

 `image` is null or a live view; `constants` is null or writable.
 */
int cavalry_image_constants(const cavalry_image_t *image,
                            cavalry_image_constants_t *constants);

/*
 The position the subscription has read the image to.

 # Safety

 `image` is null or a live view.
 */
int64_t cavalry_image_position(const cavalry_image_t *image);

/*
 Whether the image's stream has ended at the position read.

 # Safety

 `image` is null or a live view.
 */
bool cavalry_image_is_end_of_stream(const cavalry_image_t *image);

/*
 Fills `values` with the header's fields.

 # Safety

 `header` is null or the header a poll handed the handler, during that call;
 `values` is null or writable.
 */
int cavalry_header_values(const cavalry_header_t *header,
                          cavalry_header_values_t *values);

/*
 Whether the subscription has an image.

 # Safety

 `subscription` is null or a live handle not in use by another call.
 */
bool cavalry_subscription_is_connected(const cavalry_subscription_t *subscription);

/*
 Whether the subscription's client is closed.

 # Safety

 As for `cavalry_subscription_is_connected`.
 */
bool cavalry_subscription_is_closed(const cavalry_subscription_t *subscription);

/*
 Fills `constants` from the copy the handle took when it was made; allowed from
 inside the handler.

 # Safety

 `subscription` is null or a live handle; `constants` is null or writable.
 */
int cavalry_subscription_constants(const cavalry_subscription_t *subscription,
                                   cavalry_subscription_constants_t *constants);

/*
 Closes the subscription and frees the handle; refused from inside its own handler.

 # Safety

 `subscription` is null or a live handle, closed once.
 */
int cavalry_subscription_close(cavalry_subscription_t *subscription);

